/**
 * Destination for TypeScript definitions generated by:
 *
 *   npm run supabase:db:types
 *
 * The generated file replaces this placeholder. No tables or relationships are
 * declared manually so the frontend cannot drift from the actual database.
 */
export type Database = {
  public: {
    Tables: Record<string, never>
    Views: Record<string, never>
    Functions: Record<string, never>
  }
}
